"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["43291"],{74060(e){e.exports=JSON.parse('{"id":"FIN-043","slug":"investor","term":"Investor","also_known_as":[],"difficulty":"Beginner","definition":"An investor is a person or organisation that puts money into assets, such as shares, bonds, property or businesses, expecting to earn a return.","explanation":["Investors range from individuals saving for retirement to huge institutions. Individual investors, often called retail investors, invest their own money, usually through brokerage accounts, pension plans or funds. Institutional investors, such as pension funds, insurance companies, mutual funds and endowments, invest very large sums on behalf of many people.","Investors differ in their goals, time horizons and attitudes to risk. A 25-year-old saving for retirement can usually accept more ups and downs than a 70-year-old who needs a steady income now. Some investors want regular income, others want long-term growth, and some prioritise keeping their money safe.","Investors also differ in approach. Some try to pick individual winners or time the market. Others buy broad, low-cost index funds and hold them for many years.","Investors play an important role in the economy. By buying shares and bonds, they provide companies and governments with money to grow, build and operate. In return, they share in the profits through dividends, interest and rising asset values, while also bearing the risk of losses."],"note":"","total":1500,"prev":{"slug":"investment-value","term":"Investment Value"},"next":{"slug":"iron-condor","term":"Iron Condor"}}')}}]);